from __future__ import absolute_import
from taf.selenium.gnb.oam.coam.classical import pages
from .certificate_management import BtsCertificatesPage, AutomaticManagementPage, VendorCertificatesPage


class Configuration(pages.Configuration):
    """
    The class corresponding to Configuration page on selenium_coam web, all operations under Configuration
    page will be implemented or added in its corresponding classes.
    """

    def __init__(self, driver, download_checker):
        super(Configuration, self).__init__(driver, download_checker)
        self._bts_certificates = BtsCertificatesPage(driver)
        self._automatic_management = AutomaticManagementPage(driver)
        self._vendor_certificates = VendorCertificatesPage(driver)
